def compute(vars):
    beginning = vars["v1"]
    ending = vars["v2"]
    if beginning == 0:
        return None

    change = ending - beginning
    value = (change / beginning) * 100

    return {
        "value": value,
        "trace": {
            "beginning": beginning,
            "ending": ending,
            "change": change,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
